def main():
    rows = []
    for key, md, rule, nru, nen, years in F:
        assert len(years) == 4, key
        for y, (ru, en, gift) in zip(("1", "2", "3", "any"), years):
            rows.append([key, md, rule, y, nru, nen, ru, en, gift, f"fest_{key}"])
    write("festivals.tsv", COLS, rows)


if __name__ == "__main__":
    main()
